import './index.less'
import { shopifyCartAdd } from '@utils/api.js'
import { isMobile } from '@utils/index'

// 智能选购
if (!customElements.get('smart-recommend-block')) {
  customElements.define('smart-recommend-block', class SmartRecommend extends HTMLElement {
    constructor() {
      super();
      this.checked = false;
      this.innerDOM = document.createElement('div');
      this.innerDOM.classList.add('container');
      this.cartClickBound = false
      this.initEvents();

      if (document.querySelector('variant-fields')) {
        document.addEventListener('variantChangeEvent', async e => {
          const currentVariant = e.detail.variant
          if (currentVariant) {
            this.getEnergyList(currentVariant.id)
          }
        })
      }
    }
    initEvents() {
      this.skuId = this.querySelector('.smart-recommend-mb').getAttribute('data-id') || ''
      this.noDataImg = this.querySelector('.smart-recommend-mb').getAttribute('data-img') || ''
      this.noDataText = this.querySelector('.smart-recommend-mb').getAttribute('data-text') || ''
      this.getEnergyList(this.skuId)
      const that = this

      const addToCartBtn = this.querySelector('.cart-right')
      if (addToCartBtn) {
        addToCartBtn.onclick = () => {
          const selectedItems = [];

          let checkBottoms = this.querySelectorAll('.middle-item input[type=checkbox]');

          checkBottoms.forEach(cb => {
            if (cb.checked) {
              const item = cb.closest('.middle-item');
              if (item) {
                const skuid = Number(item.dataset.skuId);
                const number = Number(item.dataset.number);
                selectedItems.push({
                  id: skuid,
                  quantity: number
                });
              }
            }
          });
          let hasChecked = Array.from(checkBottoms).some(checkbox => checkbox.checked);
          if (hasChecked) {
            this.addToCart(selectedItems)

            // 数据埋码
            this.GAEvent({
              "title": that.querySelector('.smart-recommend-title').textContent || '', // 版块标题
              "module": that.querySelector('.cart-right').dataset.ganame,
              "position": that.querySelector('.cart-left').querySelector('.cart-price').querySelector('span').textContent,
              "button_name": that.querySelector('.cart-right').textContent?.trim(), // 按钮名称
            })
          }
        }
      }
    }

    // 获取电器列表
    getEnergyList(skuId) {
      return fetch(
        `${window.pageInfo.api}/osconsumerapi/cus/four/smartshop/pageenergy?shopifyShopId=${window.pageInfo.shopId}&skuId=${skuId}`,
        {
          headers: {
            cr: window?.pageInfo?.cr,
            lang: window?.pageInfo?.lang,
          },
        }
      )
        .then((response) => response.json())
        .then((res) => {
          if (res.data) {
            //sku在下拉列表中
            const exists = res.data.some(item => item.skuId === Number(skuId));
            //通过变体的sku反查gid
            let gId
            let capacity
            let variantImage
            let variantUrl
            let variantTitle
            if (exists) {
              const currentItem = res.data.find(item => item.skuId === Number(skuId));
              gId = currentItem.gId
              capacity = currentItem.capacity
              variantImage = currentItem.image
              variantUrl = currentItem.goodsUrl
              variantTitle = currentItem.title
            }
            // 给板子判断取值
            this.is_exist = String(exists)
            const that = this;
            if (exists) {
              //切换变体显示固定文案
              this.querySelector('.smart-recommend-left .is-pps').style.display = 'block';
              this.querySelector('.smart-recommend-left .is-pps').style.display = '-webkit-box';
              this.getSolarList(gId)
              let productImgSrc = this.querySelectorAll('.smart-recommend-left .left-img')
              productImgSrc.forEach(item => {
                item.innerHTML = `<img src="${variantImage}" alt="${variantTitle}">`;
              });
              this.querySelector('.smart-recommend-left .is-pps').textContent = variantTitle
              this.querySelector('.smart-recommend-left .select-container').style.display = 'none';

              this.querySelectorAll('.bottom-right .number').forEach(el => {
                if (capacity) {
                  that.querySelectorAll('.bottom-right').forEach(el => {
                    el.classList.remove('hidden');
                    el.classList.add('smart-show-flex')
                  })
                  el.textContent = capacity
                } else {
                  // 没有capacity的话居中样式
                  that.querySelectorAll('.bottom-right').forEach(el => {
                    el.classList.remove('smart-show-flex');
                    el.classList.add('hidden');
                  });
                  that.querySelector('.smart-recommend-bottom-mb').style.justifyContent = 'center';
                }
              });

              this.singleGid = gId
            } else {
              const optionsData = res.data || []

              // 如果后端只返回一个产品，则不显示下拉
              if (res.data.length === 1) {
                this.querySelector('.smart-recommend-left .is-pps').style.display = 'block';
                this.querySelector('.smart-recommend-left .is-pps').style.display = '-webkit-box';
                this.querySelector('.smart-recommend-left .is-pps').textContent = optionsData[0]?.title || ''
                this.querySelector('.smart-recommend-left .select-container').style.display = 'none';
              } else {
                this.querySelector('.smart-recommend-left .select-container').style.display = 'block';
                this.querySelector('.smart-recommend-left .is-pps').style.display = 'none';
              }

              //切换变体显示下拉
              const selectHTML = `
                <select>
                  ${optionsData.map(item => `<option value="${item.gId}">${item.title}</option>`).join('')}
                </select>
              `;

              let energyGid = optionsData[0]?.gId

              if (energyGid) {
                this.getSolarList(energyGid)
              }

              const that = this;
              this.querySelector('.smart-recommend-left .select-container').innerHTML = selectHTML;
              this.querySelector('.smart-recommend-left .select-container select')
                .addEventListener('change', function (event) {
                  const selectedValue = event.target.value;
                  that.getSolarList(selectedValue)
                  const target = optionsData.find(item => item.gId == selectedValue);

                  let productImgSrc = that.querySelectorAll('.smart-recommend-left .left-img')
                  productImgSrc.forEach(item => {
                    item.innerHTML = `<img src="${target.image}" alt="${target.title}">`;
                  });
                  that.querySelectorAll('.bottom-right .number').forEach(el => {
                    if (target.capacity) {
                      that.querySelectorAll('.bottom-right').forEach(el => {
                        el.classList.remove('hidden');
                        el.classList.add('smart-show-flex')
                      })
                      el.textContent = target.capacity
                    } else {
                      that.querySelectorAll('.bottom-right').forEach(el => {
                        el.classList.remove('smart-show-flex');
                        el.classList.add('hidden');
                      });
                      that.querySelector('.smart-recommend-bottom-mb').style.justifyContent = 'center';
                    }
                  });
                });

              //渲染第一个图片
              let productImgSrc = this.querySelectorAll('.smart-recommend-left .left-img')
              productImgSrc.forEach(item => {
                item.innerHTML = `<img src="${res.data[0].image}" alt="${res.data[0].title}">`;
              });

              // 渲染wh
              this.querySelectorAll('.bottom-right .number').forEach(el => {
                if (optionsData[0].capacity) {
                  el.textContent = optionsData[0].capacity
                  that.querySelectorAll('.bottom-right').forEach(el => {
                    el.classList.remove('hidden');
                  });
                } else {
                  that.querySelectorAll('.bottom-right').forEach(el => {
                    el.classList.add('hidden');
                  });
                  that.querySelector('.smart-recommend-bottom-mb').style.justifyContent = 'center';
                }
              });
            }
            // return Promise.resolve(true);
          } else {
            // return Promise.resolve(false);
          }
        })
        .catch((e) => {
          return Promise.reject(e);
        });
    }
    // 获取太阳板列表
    getSolarList(energyGid) {
      return fetch(
        `${window.pageInfo.api}/osconsumerapi/cus/four/smartshop/pagesolar?shopifyShopId=${window.pageInfo.shopId}&energyGid=${energyGid}`,
        {
          headers: {
            cr: window?.pageInfo?.cr,
            lang: window?.pageInfo?.lang,
          },
        }
      )
        .then((response) => response.json())
        .then((res) => {
          let solarListDiv = this.querySelector('.smart-recommend-right');
          solarListDiv.innerHTML = '';
          let itemHTML = ''
          if (res.data.length > 0) {

            const updated = res.data.map(item => {
              const defaultId = item.defaultSmartShopEnergySolarRelId;
              const matched = item.solarRelResps?.find(solar => solar.smartShopEnergySolarRelId === defaultId);
              return {
                ...item,
                performance: matched?.performance ?? null,
                chargingDuration: matched?.chargingDuration ?? null
              };
            });

            if (isMobile()) {
              this.querySelectorAll('.smart-recommend-subtitle.show-mb').forEach(el => {
                el.classList.remove('hidden');
              });

              this.querySelectorAll('.smart-recommend-bottom-mb').forEach(el => {
                el.classList.remove('hidden');
              });
            } else {
              this.querySelectorAll('.smart-recommend-subtitle.show-pc').forEach(el => {
                el.classList.remove('hidden');
              });
              this.querySelectorAll('.smart-recommend-bottom').forEach(el => {
                el.classList.remove('hidden');
              });
            }

            this.querySelector('.show-result')?.classList.remove('hidden');

            updated?.forEach((item, index) => {
              if (updated.length == 1) {
                if (isMobile()) {
                  //mb太阳板样式一样
                  this.querySelector('.smart-recommend-right')?.classList.remove('one');
                  this.querySelector('.smart-recommend-right')?.classList.remove('two');
                  this.querySelector('.smart-recommend-right')?.classList.remove('active');
                  this.querySelector('.smart-recommend-mb')?.classList.remove('active')
                  this.querySelector('.smart-recommend-right')?.classList.add('three')
                  const maxPerformance = Math.max(...item.solarRelResps.map(opt => opt.performance));
                  itemHTML = `
                    <div class="item show-one" data-gid="${item.gId}">
                      <input type="checkbox" id="scales-${index}" name="scales-${index}" data-chargingDuration="${item.chargingDuration}" style="opacity: 0.5;"/>
                      <div class="item-img">
                        <img src="${item.image}" alt="${item.title}" />
                      </div>
                      <div class="item-right">
                        <div class="item-title text-overflow-2">
                          <a href="${item.goodsUrl}" target="_blank">
                            ${item.title}
                          </a>
                        </div>
                        <div class="right-bottom">
                          <div class="star">
                            ${'<svg width="20px" height="19px" viewBox="0 0 20 19" xmlns="http://www.w3.org/2000/svg" fill="#F9E00F"><polygon points="10 15 4.12 18.09 5.24 11.54 0.49 6.91 7.06 5.95 10 0 12.94 5.95 19.51 6.91 14.76 11.54 15.88 18.09"/></svg>'.repeat(item.performance)}
                          </div>
                          <div class="select-container-item">
                            <select>
                              ${item.solarRelResps.map(opt => `<option value="${opt.solarNum}" data-chargingDuration="${opt.chargingDuration}" data-performance="${opt.performance}"  ${opt.performance === maxPerformance ? 'selected' : ''}>${opt.solarNum}</option>`).join('')}
                            </select>
                          </div>
                        </div>
                      </div>
                    </div>
                  `;
                } else {
                  const maxPerformance = Math.max(...item.solarRelResps.map(opt => opt.performance));
                  this.querySelector('.smart-recommend-right')?.classList.remove('two');
                  this.querySelector('.smart-recommend-right')?.classList.remove('three');
                  this.querySelector('.smart-recommend-right')?.classList.remove('active');
                  this.querySelector('.smart-recommend-mb')?.classList.remove('active')

                  this.querySelector('.smart-recommend-right')?.classList.add('one');
                  itemHTML = `
                    <div class="item item-one" data-gid="${item.gId}">
                      <input type="checkbox" id="scales-${index}" name="scales-${index}" data-chargingDuration="${item.chargingDuration}" style="opacity: 0.5;"/>
                      <div class="item-img">
                        <img src="${item.image}" alt="${item.title}" />
                      </div>
                      <div class="item-right">
                        <div class="right-top">
                          <div class="item-title text-overflow-2">
                            <a href="${item.goodsUrl}" target="_blank">
                              ${item.title}
                            </a>
                          </div>
                          <div class="select-container-item">
                            <select>
                              ${item.solarRelResps.map(opt => `<option value="${opt.solarNum}" data-chargingDuration="${opt.chargingDuration}" data-performance="${opt.performance}" ${opt.performance === maxPerformance ? 'selected' : ''}>${opt.solarNum}</option>`).join('')}
                            </select>
                          </div>
                        </div>
                        <div class="right-bottom">
                          <div class="star">
                            ${'<svg width="20px" height="19px" viewBox="0 0 20 19" xmlns="http://www.w3.org/2000/svg" fill="#F9E00F"><polygon points="10 15 4.12 18.09 5.24 11.54 0.49 6.91 7.06 5.95 10 0 12.94 5.95 19.51 6.91 14.76 11.54 15.88 18.09"/></svg>'.repeat(item.performance)}
                          </div>
                        </div>
                      </div>
                    </div>
                  `;
                }
              } else if (updated.length == 2) {
                const maxPerformance = Math.max(...item.solarRelResps.map(opt => opt.performance));
                this.querySelector('.smart-recommend-right')?.classList.remove('one');
                this.querySelector('.smart-recommend-right')?.classList.remove('three');
                this.querySelector('.smart-recommend-right')?.classList.remove('active');
                this.querySelector('.smart-recommend-mb')?.classList.remove('active')

                this.querySelector('.smart-recommend-right')?.classList.add('two')
                itemHTML = `
                  <div class="item show-one" data-gid="${item.gId}">
                    <input type="checkbox" id="scales-${index}" name="scales-${index}" data-chargingDuration="${item.chargingDuration}"/>
                    <div class="item-img">
                      <img src="${item.image}" alt="${item.title}" />
                    </div>
                    <div class="item-right">
                      <div class="item-title text-overflow-2">
                        <a href="${item.goodsUrl}" target="_blank">
                          ${item.title}
                        </a>
                      </div>
                      <div class="right-bottom">
                        <div class="star">
                          ${'<svg width="20px" height="19px" viewBox="0 0 20 19" xmlns="http://www.w3.org/2000/svg" fill="#F9E00F"><polygon points="10 15 4.12 18.09 5.24 11.54 0.49 6.91 7.06 5.95 10 0 12.94 5.95 19.51 6.91 14.76 11.54 15.88 18.09"/></svg>'.repeat(item.performance)}
                        </div>
                        <div class="select-container-item">
                          <select>
                            ${item.solarRelResps.map(opt => `<option value="${opt.solarNum}" data-chargingDuration="${opt.chargingDuration}" data-performance="${opt.performance}" data-chargingDuration="${opt.chargingDuration}" ${opt.performance === maxPerformance ? 'selected' : ''}>${opt.solarNum}</option>`).join('')}
                          </select>
                        </div>
                      </div>
                    </div>
                  </div>
                `;
              } else if (updated.length == 3) {
                const maxPerformance = Math.max(...item.solarRelResps.map(opt => opt.performance));

                this.querySelector('.smart-recommend-right')?.classList.remove('one');
                this.querySelector('.smart-recommend-right')?.classList.remove('two');
                this.querySelector('.smart-recommend-right')?.classList.remove('active');
                this.querySelector('.smart-recommend-mb')?.classList.remove('active')

                this.querySelector('.smart-recommend-right')?.classList.add('three')
                itemHTML = `
                  <div class="item show-one" data-gid="${item.gId}">
                    <input type="checkbox" id="scales-${index}" name="scales-${index}" data-chargingDuration="${item.chargingDuration}"/>
                    <div class="item-img">
                      <img src="${item.image}" alt="${item.title}" />
                    </div>
                    <div class="item-right">
                      <div class="item-title text-overflow-2">
                        <a href="${item.goodsUrl}" target="_blank">
                          ${item.title}
                        </a>
                      </div>
                      <div class="right-bottom">
                        <div class="star">
                          ${'<svg width="20px" height="19px" viewBox="0 0 20 19" xmlns="http://www.w3.org/2000/svg" fill="#F9E00F"><polygon points="10 15 4.12 18.09 5.24 11.54 0.49 6.91 7.06 5.95 10 0 12.94 5.95 19.51 6.91 14.76 11.54 15.88 18.09"/></svg>'.repeat(item.performance)}
                        </div>
                        <div class="select-container-item">
                          <select>
                            ${item.solarRelResps.map(opt => `<option value="${opt.solarNum}" data-chargingDuration="${opt.chargingDuration}" data-performance="${opt.performance}" ${opt.performance === maxPerformance ? 'selected' : ''}>${opt.solarNum}</option>`).join('')}
                          </select>
                        </div>
                      </div>
                    </div>
                  </div>
                `;
              }
              else {
                const maxPerformance = Math.max(...item.solarRelResps.map(opt => opt.performance));
                this.querySelector('.smart-recommend-right')?.classList.remove('one');
                this.querySelector('.smart-recommend-right')?.classList.remove('two');
                this.querySelector('.smart-recommend-right')?.classList.remove('three');
                this.querySelector('.smart-recommend-right')?.classList.add('active');
                this.querySelector('.smart-recommend-mb')?.classList.add('active')
                itemHTML = `
                  <div class="item show-one" data-gid="${item.gId}">
                    <input type="checkbox" id="scales-${index}" name="scales-${index}" data-chargingDuration="${item.chargingDuration}"/>
                    <div class="item-img">
                      <img src="${item.image}" alt="${item.title}" />
                    </div>
                    <div class="item-right">
                      <div class="item-title text-overflow-2">
                        <a href="${item.goodsUrl}" target="_blank">
                          ${item.title}
                        </a>
                      </div>
                      <div class="right-bottom">
                        <div class="star">
                          ${'<svg width="20px" height="19px" viewBox="0 0 20 19" xmlns="http://www.w3.org/2000/svg" fill="#F9E00F"><polygon points="10 15 4.12 18.09 5.24 11.54 0.49 6.91 7.06 5.95 10 0 12.94 5.95 19.51 6.91 14.76 11.54 15.88 18.09"/></svg>'.repeat(item.performance)}
                        </div>
                        <div class="select-container-item">
                          <select>
                            ${item.solarRelResps.map(opt => `<option value="${opt.solarNum}" data-chargingDuration="${opt.chargingDuration}" data-performance="${opt.performance}" ${opt.performance === maxPerformance ? 'selected' : ''}>${opt.solarNum}</option>`).join('')}
                          </select>
                        </div>
                      </div>
                    </div>
                  </div>
                `;
              }

              solarListDiv.insertAdjacentHTML('beforeend', itemHTML);
            });

            //渲染hrs
            this.querySelectorAll('.bottom-left .number').forEach(el => {
              el.textContent = updated[0].chargingDuration
            });
            // 勾选默认逻辑
            let checkboxes = this.querySelectorAll('.smart-recommend-right .item input[type=checkbox]');
            const that = this;
            checkboxes.forEach((checkbox) => {
              checkbox.addEventListener('change', function () {
                // 先移除所有 item 的 active 状态
                checkboxes.forEach(cb => {
                  cb.closest('.item').classList.remove('active');
                  if (cb !== this) cb.checked = false; // 互斥勾选
                });

                // 如果当前是选中的，就加上 active
                if (this.checked) {
                  this.closest('.item').classList.add('active');
                  that.querySelectorAll('.bottom-left .number').forEach(el => {
                    el.textContent = this.getAttribute('data-chargingDuration');
                  });
                  const item = this.closest('.item');
                  const itemRight = item.querySelector('.item-right .select-container-item select');

                  //获取配件
                  let params = {
                    energyGid: that.is_exist === 'true' ? that.singleGid : that.querySelector('.smart-recommend-left .select-container select').value,
                    solarGid: item.getAttribute('data-gid'),
                    solarNum: itemRight.value
                  }

                  if (that.querySelector('.show-result')) {
                    that.getAccessList(params)
                  }
                }
              });
            });
            // 默认勾选第一个
            const first = checkboxes[0];
            if (first) {
              first.checked = true;
              first.closest('.item').classList.add('active');
              first.dispatchEvent(new Event('change', { bubbles: true }));
            }

            //下拉框change
            this.querySelectorAll('.smart-recommend-right .select-container-item select')
              .forEach(select => {
                select.addEventListener('change', function (event) {
                  const selectedOption = event.target.selectedOptions[0];
                  const duration = selectedOption.getAttribute('data-chargingDuration');
                  that.querySelectorAll('.bottom-left .number').forEach(el => el.textContent = duration);

                  //更新星星
                  const starNumber = selectedOption.getAttribute('data-performance')

                  const starContainer = this.closest('.item-right').querySelector('.star');
                  starContainer.innerHTML = `${'<svg width="20px" height="19px" viewBox="0 0 20 19" xmlns="http://www.w3.org/2000/svg" fill="#F9E00F"><polygon points="10 15 4.12 18.09 5.24 11.54 0.49 6.91 7.06 5.95 10 0 12.94 5.95 19.51 6.91 14.76 11.54 15.88 18.09"/></svg>'.repeat(starNumber)}`

                  // return
                  //获取配件
                  let params = {
                    energyGid: that.is_exist === 'true' ? that.singleGid : that.querySelector('.smart-recommend-left .select-container select').value,
                    solarGid: event.target.closest('.item').getAttribute('data-gid'),
                    solarNum: event.target.value
                  }
                  if (that.querySelector('.show-result')) {
                    that.getAccessList(params)
                  }
                });
              });

            this.querySelectorAll('.smart-recommend-right .item').forEach(item => {
              item.addEventListener('click', (e) => {
                // 如果点的是checkbox本身，直接return，什么都不做
                const checkbox = item.querySelector('input[type="checkbox"]');

                if (!checkbox || checkbox?.checked) return; // 没有checkbox || 已经选中了，直接返回

                if (e.target === checkbox) {
                  // 如果点的是checkbox自己，阻止默认行为，不让它自己处理
                  e.preventDefault();
                  return;
                }

                // 切换逻辑：把自己选中，取消别人
                checkbox.checked = true;
                const event = new Event('change', { bubbles: true });
                checkbox.dispatchEvent(event); // 手动触发change
              });
            });

            this.querySelectorAll('.item-title a').forEach(img => {
              img.addEventListener('click', function () {
                // 数据埋码
                that.GAEvent({
                  "title": that.querySelector('.smart-recommend-title').textContent || '', // 版块标题
                  "module": this.textContent.trim(),
                  "button_name": 'Text_link', // 按钮名称
                  "link": this.getAttribute('href')
                })
              });
            });
          } else {
            //没有太阳板的情况
            this.querySelectorAll('.smart-recommend-bottom').forEach(el => el.classList.add('hidden'));
            this.querySelectorAll('.smart-recommend-bottom-mb').forEach(el => el.classList.add('hidden'));
            this.querySelectorAll('.smart-recommend-subtitle').forEach(el => el.classList.add('hidden'));

            this.querySelector('.show-result')?.classList.add('hidden');

            const smartRight = this.querySelector('.smart-recommend-right');
            const smartMb = this.querySelector('.smart-recommend-mb');
            // 清除公共类
            smartRight?.classList.remove('two', 'three', 'active');
            smartMb?.classList.remove('active');
            if (isMobile()) {
              //mb太阳板样式一样
              smartRight?.classList.add('no-data');
              itemHTML = `
                <div class="no-data-content">
                  <div class="no-data-img">
                    <img src="${this.noDataImg}" alt="no data" loading="lazy">
                  </div>
                  <p class="no-data-text">${this.noDataText}</p>
                </div>
              `;
            } else {
              // 桌面端样式处理
              smartRight?.classList.add("one");
              itemHTML = `
                <div class="item item-one item-no-data">
                  <div class="no-data-img">
                    <img src="${this.noDataImg}" alt="no data" loading="lazy">
                  </div>
                  <p class="no-data-text">${this.noDataText}</p>
                </div>
              `;
            }
            solarListDiv.insertAdjacentHTML('beforeend', itemHTML);
          }
        })
        .catch((e) => {
          return Promise.reject(e);
        });
    }
    // 获取配件列表
    getAccessList(params) {
      return fetch(
        `${window.pageInfo.api}/osconsumerapi/cus/four/smartshop/solution?shopifyShopId=${window.pageInfo.shopId}&energyGid=${params.energyGid}&solarGid=${params.solarGid}&solarNum=${params.solarNum}`,
        {
          headers: {
            cr: window?.pageInfo?.cr,
            lang: window?.pageInfo?.lang,
          },
        }
      )
        .then((response) => response.json())
        .then((res) => {
          if (res.data) {
            const that = this;
            let energySolarProductList = res.data.energySolarProductList
            let partsProductList = res.data.partsProductList
            let energySolarDiv = this.querySelector('.smart-recommend-middle .middle-center')
            let partDiv = this.querySelector('.smart-recommend-access .middle-center')

            energySolarDiv.innerHTML = '';
            energySolarProductList?.forEach((item, index) => {
              // 是否开启了自动折扣价
              const open_auto_discount_price = document.querySelector("smart-recommend-block").getAttribute("data-open-auto-discount-price") === "true"
              const current_price = Math.min(item.autoDiscountPrice || 0, item.shopifyFrontprice || 0)
              const origin_price = Math.max(item.autoDiscountPrice || 0, item.shopifyFrontprice || 0, item.shopifyFrontOriginalPrice || 0)

              const calPrice = open_auto_discount_price && item.autoDiscountPrice > 0 ? current_price : item.shopifyFrontprice
              const calOriginPrice = open_auto_discount_price && item.autoDiscountPrice > 0
                ? (origin_price > current_price ? origin_price : 0)
                : (item.shopifyFrontprice < item.shopifyFrontOriginalPrice
                  ? item.shopifyFrontOriginalPrice
                  : 0);
              let itemHTML = `
                <div
                  class="middle-item"
                  data-sku-id="${item.skuId}"
                  data-price="${calPrice}"
                  data-originprice="${calOriginPrice}"
                  data-number="${item.solarNum || 1}"
                >
                  <input type="checkbox" id="scales" name="scales" checked/>
                  <div class="middle-img">
                    <img src="${item.image}" alt="${item.title}" />
                  </div>
                  <div class="middle-text">
                    <div class="middle-text-top text-overflow-2">
                      <a href="${item.goodsUrl}" target="_blank">${item.title}</a> 
                    </div>
                    <div class="middle-text-bottom">
                      <div class="bottom-price-box">
                        <div class="bottom-price">
                          ${open_auto_discount_price && item.autoDiscountPrice > 0
                            ? window.formatMoney(current_price)
                            : window.formatMoney(item.shopifyFrontprice, window?.pageInfo?.currency?.money_format)
                          }
                        </div>
                        ${open_auto_discount_price && item.autoDiscountPrice > 0
                          ? `<div class="bottom-origin-price">${origin_price > current_price ? window.formatMoney(origin_price) : ''}</div>`
                          : item.shopifyFrontprice < item.shopifyFrontOriginalPrice
                            ? `<div class="bottom-origin-price">
                                ${window.formatMoney(item.shopifyFrontOriginalPrice, window?.pageInfo?.currency?.money_format)}
                              </div>`
                            : ""
                        }
                      </div>
                      <div class="middle-number"> x ${item.solarNum}</div>
                    </div>
                  </div>
                </div>
              `;

              if (energySolarProductList.length == 1) {
                const cartText = that.querySelector('.smart-recommend-mb').getAttribute('data-cart')
                itemHTML = `
									<div class="middle-item middle-item-only" data-sku-id="${item.skuId}" data-price="${calPrice}" data-originprice="${calOriginPrice}" data-number="${item.solarNum || 1}">
										<div class="middle-img">
											<img src="${item.image}" alt="${item.title}" />
										</div>
										<div class="middle-text">
											<div class="middle-text-top text-overflow-2">
                        <a href="${item.goodsUrl}" target="_blank">
												  ${item.title}
                        </a>
											</div>
											<div class="middle-text-bottom">
												<div class="bottom-price-box">
													<div class="bottom-price">
														${open_auto_discount_price && item.autoDiscountPrice > 0
                              ? window.formatMoney(current_price)
                              : window.formatMoney(item.shopifyFrontprice, window?.pageInfo?.currency?.money_format)
                            }
													</div>
													${open_auto_discount_price && item.autoDiscountPrice > 0
                            ? `<div class="bottom-origin-price">${origin_price > current_price ? window.formatMoney(origin_price) : ''}</div>`
                            : item.shopifyFrontprice < item.shopifyFrontOriginalPrice
                              ? `<div class="bottom-origin-price">
                                  ${window.formatMoney(item.shopifyFrontOriginalPrice, window?.pageInfo?.currency?.money_format)}
                                </div>`
                              : ""
                          }
												</div>
												<a class="cart-right-only" href="javascript:void(0)">${cartText}</a>
											</div>
										</div>
									</div>
								`;

                if (!this.cartClickBound) {
                  this.addEventListener('click', function (event) {
                    const cartRightEl = event.target.closest('.cart-right-only');
                    if (cartRightEl) {
                      const parent = cartRightEl.closest('.middle-item-only');
                      if (parent) {
                        const skuId = parent.getAttribute('data-sku-id');
                        const number = parent.getAttribute('data-number');
                        that.addToCart([{ id: skuId, quantity: number }])
                        // 数据埋码
                        this.GAEvent({
                          "title": that.querySelector('.smart-recommend-title').textContent || '', // 版块标题
                          "module": that.querySelector('.middle-text-top').querySelector('a').textContent.trim(),
                          "position": that.querySelector('.bottom-price').textContent.trim(),
                          "button_name": that.querySelector('.cart-right-only').textContent.trim() // 按钮名称
                        })
                      }
                    }
                  });
                  this.cartClickBound = true
                }

                that.querySelectorAll('.smart-recommend-access, .smart-recommend-cart').forEach(el => el.style.display = 'none');
              } else if (energySolarProductList.length == 2) {
                if (partsProductList?.length >= 1) {
                  that.querySelector('.smart-recommend-access').style.display = "block";
                } else {
                  that.querySelector('.smart-recommend-access').style.display = "none";
                }
                that.querySelector('.smart-recommend-cart').style.display = "flex";
              }
              else {
                that.querySelector('.smart-recommend-access').style.display = "block";
                that.querySelector('.smart-recommend-cart').style.display = "flex";
              }

              energySolarDiv.insertAdjacentHTML('beforeend', itemHTML);
            });

            partDiv.innerHTML = '';
            partsProductList?.forEach((item, index) => {
              // 是否开启了自动折扣价
              const open_auto_discount_price = document.querySelector("smart-recommend-block").getAttribute("data-open-auto-discount-price") === "true"
              const current_price = Math.min(item.autoDiscountPrice || 0, item.shopifyFrontprice || 0)
              const origin_price = Math.max(item.autoDiscountPrice || 0, item.shopifyFrontprice || 0, item.shopifyFrontOriginalPrice || 0)
              const calPrice = open_auto_discount_price && item.autoDiscountPrice > 0 ? current_price : item.shopifyFrontprice
              const calOriginPrice = open_auto_discount_price && item.autoDiscountPrice > 0
                ? (origin_price > current_price ? origin_price : 0)
                : (item.shopifyFrontprice < item.shopifyFrontOriginalPrice
                  ? item.shopifyFrontOriginalPrice
                  : 0);

              let itemHTML = `
                <div class="middle-item" data-sku-id="${item.skuId}" data-price="${calPrice}" data-originprice="${calOriginPrice}" data-number="${item.solarNum}">
                  <input type="checkbox" id="scales" name="scales" checked/>
                  <div class="middle-img">
                    <img src="${item.image}" alt="${item.title}" />
                  </div>
                  <div class="middle-text">
                    <div class="middle-text-top text-overflow-2">
                      <a href="${item.goodsUrl}" target="_blank">
                        ${item.title}
                      </a>
                    </div>
                    <div class="middle-text-bottom">
                      <div class="bottom-price-box">
                        <div class="bottom-price">
                          ${open_auto_discount_price && item.autoDiscountPrice > 0
                            ? window.formatMoney(current_price)
                            : window.formatMoney(item.shopifyFrontprice, window?.pageInfo?.currency?.money_format)
                          }
                        </div>
                        ${open_auto_discount_price && item.autoDiscountPrice > 0
                          ? `<div class="bottom-origin-price">${origin_price > current_price ? window.formatMoney(origin_price) : ''}</div>`
                          : item.shopifyFrontprice < item.shopifyFrontOriginalPrice
                            ? `<div class="bottom-origin-price">
                                ${window.formatMoney(item.shopifyFrontOriginalPrice, window?.pageInfo?.currency?.money_format)}
                              </div>`
                            : ""
                        }
                      </div>
                      <div class="middle-number">
                        x ${item.solarNum}
                      </div>
                    </div>
                  </div>
                </div>
              `;

              partDiv.insertAdjacentHTML('beforeend', itemHTML);
            });

            //监听下面的产品和配件
            let checkBottoms = this.querySelectorAll('.middle-item input[type=checkbox]');

            checkBottoms.forEach((checkbox) => {
              checkbox.addEventListener('change', function () {

                // 如果当前是选中的，就加上 active
                if (this.checked) {
                  this.closest('.middle-item').classList.add('active');
                } else {
                  this.closest('.middle-item').classList.remove('active');
                }
                // 计算所有被选中的 checkbox 对应的价格总和
                let totalPrice = 0;
                let beforeTotalPrice = 0;
                let TotalProduct = '';
                let index = 0;
                checkBottoms.forEach(cb => {
                  if (cb.checked) {
                    const item = cb.closest('.middle-item');
                    const number = item.dataset.number
                    const price = item.dataset.price;
                    const productName = item.querySelector('.middle-text-top').querySelector('a').textContent.trim().replace(/\s+/g, '');
                    let middleProduct = index === 0 ? productName : productName + "(" + number + ")";
                    TotalProduct += middleProduct + "+";

                    let beforePrice = item.dataset.originprice;
                    if (beforePrice == 'null' || beforePrice == '0') {
                      beforePrice = item.dataset.price;
                    }

                    let middlePrice = price * number
                    let middleBeforePrice = beforePrice * number
                    if (!isNaN(price)) {
                      totalPrice += middlePrice;
                    }
                    if (!isNaN(beforePrice)) {
                      beforeTotalPrice += middleBeforePrice;
                    }
                    index++;
                  }

                  let hasChecked = Array.from(checkBottoms).some(cb => cb.checked);
                  let targetEl = that.querySelector('.smart-recommend-cart .cart-right');
                  if (!hasChecked) {
                    targetEl.style.backgroundColor = '#ccc';
                    targetEl.style.cursor = 'not-allowed';
                  } else {
                    targetEl.style.backgroundColor = 'var(--jds-color-primary)';
                    targetEl.style.cursor = 'pointer';
                  }
                });
                if (TotalProduct.endsWith("+")) {
                  TotalProduct = TotalProduct.slice(0, -1);
                }

                that.querySelector('.cart-right').dataset.ganame = TotalProduct;

                const originPriceEl = that.querySelector('.smart-recommend-cart .cart-origin-price')

                let $totalPrice = window.formatMoney(totalPrice, window?.pageInfo?.currency?.money_format)
                let $beforeTotalPrice = window.formatMoney(beforeTotalPrice, window?.pageInfo?.currency?.money_format)
                const priceEl = that.querySelector('.smart-recommend-cart .cart-price span')
                if (priceEl) {
                  priceEl.textContent = $totalPrice
                }

                if (beforeTotalPrice <= totalPrice) {
                  originPriceEl.textContent = ''
                } else {
                  originPriceEl.textContent = $beforeTotalPrice
                }
              });
            });
            checkBottoms.forEach((checkbox) => {
              checkbox.checked = true;
              checkbox.dispatchEvent(new Event('change'));
            });

            checkBottoms.forEach((checkbox) => {
              checkbox.addEventListener('click', (e) => {
                e.stopPropagation(); // 阻止 click 冒泡到 .middle-item
              });
            })

            // 点击配件列表
            this.querySelectorAll('.middle-item').forEach(item => {
              item.addEventListener('click', (e) => {
                // 如果点的是checkbox本身，直接return，什么都不做
                const checkbox = item.querySelector('input[type="checkbox"]');
                //点击a标签不触发
                if (e.target.closest('a')) return;

                if (!checkbox) return; // 没有checkbox直接返回

                if (checkbox.checked) {
                  checkbox.checked = false;
                  checkbox.dispatchEvent(new Event('change', { bubbles: true }));
                  return;
                }

                // 切换逻辑：把自己选中，取消别人
                checkbox.checked = true;
                const event = new Event('change', { bubbles: true });
                checkbox.dispatchEvent(event); // 手动触发change
              });
            });

            this.querySelectorAll('.middle-text-top a').forEach(img => {
              img.addEventListener('click', function () {
                // 数据埋码
                that.GAEvent({
                  "title": that.querySelector('.smart-recommend-title').textContent || '', // 版块标题
                  "module": this.textContent.trim(),
                  "button_name": 'Text_link', // 按钮名称
                  "link": this.getAttribute('href'),
                  "position": this.closest('.middle-item').querySelector('.bottom-price').textContent.trim(),
                })
              });
            });
          }
        })
        .catch((e) => {
          return Promise.reject(e);
        });
    }
    // 加购
    addToCart(items) {
      const cart = document.querySelector('cart-notification') || document.querySelector('cart-drawer')
      shopifyCartAdd({ items }).then(r => {
        if (cart && cart.renderContents) {
          cart.renderContents(r)
        } else {
          window.location.href = '/cart'
        }
      }).catch(err => {
        console.log(err)
      })
    }
    // 数据埋码
    GAEvent(params) {
      window.dataLayer.push({ "event_parameters": null });
      window.dataLayer.push({
        "event": "ga4Event",
        "event_name": "smart_recommend_user_clicks",
        "event_parameters": {
          "current_page": window.location.href, // current page url
          ...params
        }
      });
    }
  });
}
